import sys
sys.setrecursionlimit(100000)
(n, r1, r2) = map(int, input().split())
a = list(map(int, input().split()))
g = {}
num = 0
for (k, v) in enumerate(a):
	num += 1
	if num == r1:
		num += 1
	if num not in g:
		g[num] = []
	g[num].append(v)
	if v not in g:
		g[v] = []
	g[v].append(num)
b = [0] * (n + 1)
visited = set()

def visit(cur, parent):
	visited.add(cur)
	b[cur] = parent
	for child in g[cur]:
		if child not in visited:
			visit(child, cur)
from collections import deque
q = deque()
q.append((r2, 0))
while q:
	(cur, parent) = q.popleft()
	if cur not in visited:
		visited.add(cur)
		b[cur] = parent
		for child in g[cur]:
			q.append((child, cur))
b2 = [b[k] for k in range(n + 1) if k > 0 and k != r2]
print(*b2)
